package world.yemyat.slicepilot.model

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import world.yemyat.slicepilot.preview.PreviewGeometry
import java.io.File

class GcodePreviewMultiColourTest {
    @Test
    fun `parses semicolon-separated filament colours and per-tool toolpaths`() {
        val tmp = File.createTempFile("multicolour_test", ".gcode")
        try {
            tmp.writeText(
                """
                ; generated by SlicePilot
                ; LAYER_COUNT: 1
                ; filament used [mm] = 120.5, 45.5
                ; filament used [g] = 0.36, 0.14
                M83
                ;LAYER_CHANGE
                ;TYPE:Outer wall
                T0
                G1 X0 Y0 Z0.2
                G1 X10 Y0 E1.0
                T1
                G1 X10 Y10 Z0.2
                G1 X20 Y10 E1.0
                ; filament_colour = #FF0000;#00FF00
                """.trimIndent(),
            )
            val preview = GcodePreviewParser.parse(tmp)
            assertEquals(listOf("#FF0000", "#00FF00"), preview.filamentColors)
            assertEquals(1, preview.layers.size)
            val tools = preview.layers[0].parts.map { it.tool }.toSet()
            assertEquals(setOf(0, 1), tools)

            val gpuParts = PreviewGeometry.gcodeParts(preview, PreviewGeometry.GCODE_DEFAULT_COLOR)
            val t0 = gpuParts.first { it.tool == 0 }
            val t1 = gpuParts.first { it.tool == 1 }
            assertEquals(1f, t0.color[0], 0.01f)
            assertEquals(0f, t0.color[1], 0.01f)
            assertEquals(0f, t1.color[0], 0.01f)
            assertEquals(1f, t1.color[1], 0.01f)

            val stats = GcodePreviewParser.parseStats(tmp)
            assertEquals(166.0f, stats.filamentMm ?: 0f, 0.05f)
            assertEquals(0.50f, stats.filamentGrams ?: 0f, 0.01f)
            assertTrue(stats.filamentColor?.contains("#FF0000") == true)
        } finally {
            tmp.delete()
        }
    }
}
